/**
 * Syntax themes — port of @astryxdesign/core theme/syntax/defineSyntaxTheme.ts (+ the preset
 * names of presets.ts). The preset palettes themselves ship as CSS in
 * `src/styles/syntax.css` (generated by scripts/build-syntax.mjs), keyed by
 * `[data-astryx-syntax-theme="<name>"]`, so a preset needs no inline style.
 *
 *   <SyntaxTheme theme="dracula">…</SyntaxTheme>
 *   const brand = defineSyntaxTheme({name: 'brand', tokens: {keyword: ['#0064E0', '#2694FE'], …}});
 *   <SyntaxTheme theme={brand}>…</SyntaxTheme>
 */

/** Human-readable syntax token name (without the `--color-syntax-` prefix). */
export type SyntaxThemeTokenKey =
  | 'keyword' | 'string' | 'comment' | 'number' | 'function' | 'type' | 'variable' | 'operator'
  | 'constant' | 'tag' | 'attribute' | 'property' | 'punctuation' | 'background'
  | DiffSyntaxThemeTokenKey;

/** The diff row slots a syntax theme may set; unset ones keep their defaults. */
export type DiffSyntaxThemeTokenKey = 'added' | 'removed' | 'diff-header' | 'added-marker' | 'removed-marker';

/** A single CSS value, or a [light, dark] tuple (→ `light-dark()`). */
export type SyntaxTokenValue = string | [light: string, dark: string];

export type SyntaxThemeTokenInput = Record<Exclude<SyntaxThemeTokenKey, DiffSyntaxThemeTokenKey>, SyntaxTokenValue> &
  Partial<Record<DiffSyntaxThemeTokenKey, SyntaxTokenValue>>;

export type SyntaxThemeTokenMap = Record<Exclude<SyntaxThemeTokenKey, DiffSyntaxThemeTokenKey>, string> &
  Partial<Record<DiffSyntaxThemeTokenKey, string>>;

export interface SyntaxThemeInput {
  name: string;
  tokens: SyntaxThemeTokenInput;
}

export interface SyntaxThemeDefinition {
  name: string;
  /** Resolved values (tuples → light-dark()). */
  tokens: SyntaxThemeTokenMap;
  /** The original input (keeps tuples for per-mode resolution). */
  __inputTokens: SyntaxThemeTokenInput;
}

/** The built-in presets (Astryx presets.ts), styled by src/styles/syntax.css. */
export const syntaxPresetNames = [
  'one-dark-pro', 'dracula', 'monokai', 'nord', 'tokyo-night', 'catppuccin-mocha', 'github-dark',
  'github-light', 'solarized-light', 'one-light', 'catppuccin-latte', 'tokyo-night-light',
] as const;
export type SyntaxPresetName = (typeof syntaxPresetNames)[number];

/** The default value of each slot (Astryx syntax/tokens.ts `syntaxTokenDefaults`). */
export const syntaxTokenDefaults: Readonly<Record<`--color-syntax-${SyntaxThemeTokenKey}`, string>> = {
  '--color-syntax-keyword': 'var(--color-text-accent)',
  '--color-syntax-string': 'var(--color-text-green)',
  '--color-syntax-comment': 'var(--color-text-secondary)',
  '--color-syntax-number': 'var(--color-text-orange)',
  '--color-syntax-function': 'var(--color-text-blue)',
  '--color-syntax-type': 'var(--color-text-purple)',
  '--color-syntax-variable': 'var(--color-text-primary)',
  '--color-syntax-operator': 'var(--color-text-cyan)',
  '--color-syntax-constant': 'var(--color-text-orange)',
  '--color-syntax-tag': 'var(--color-text-red)',
  '--color-syntax-attribute': 'var(--color-text-teal)',
  '--color-syntax-property': 'var(--color-text-cyan)',
  '--color-syntax-punctuation': 'var(--color-text-secondary)',
  '--color-syntax-background': 'var(--color-background-muted)',
  '--color-syntax-added': 'color-mix(in srgb, var(--color-success-muted) 25%, transparent)',
  '--color-syntax-removed': 'color-mix(in srgb, var(--color-error-muted) 25%, transparent)',
  '--color-syntax-diff-header': 'var(--color-background-muted)',
  '--color-syntax-added-marker': 'var(--color-text-green)',
  '--color-syntax-removed-marker': 'var(--color-text-red)',
};

const PREFIX = '--color-syntax-';
export const ALL_SYNTAX_KEYS = Object.keys(syntaxTokenDefaults).map((k) => k.slice(PREFIX.length)) as SyntaxThemeTokenKey[];
const DIFF_KEYS = new Set<SyntaxThemeTokenKey>(['added', 'removed', 'diff-header', 'added-marker', 'removed-marker']);
const MARKER_KEYS = new Set<SyntaxThemeTokenKey>(['added-marker', 'removed-marker']);
export const REQUIRED_SYNTAX_KEYS = ALL_SYNTAX_KEYS.filter((k) => !DIFF_KEYS.has(k));

const resolveValue = (value: SyntaxTokenValue) => (Array.isArray(value) ? `light-dark(${value[0]}, ${value[1]})` : value);

/** Create a syntax theme from a complete token map (Astryx `defineSyntaxTheme`). */
export function defineSyntaxTheme(input: SyntaxThemeInput): SyntaxThemeDefinition {
  const missing = REQUIRED_SYNTAX_KEYS.filter((key) => !(key in input.tokens));
  if (missing.length > 0 && (import.meta as {env?: {DEV?: boolean}}).env?.DEV) {
    console.warn(`[astryx] defineSyntaxTheme "${input.name}": missing tokens: ${missing.join(', ')}.`);
  }
  const resolved: Partial<Record<SyntaxThemeTokenKey, string>> = {};
  for (const key of ALL_SYNTAX_KEYS) {
    const value = (input.tokens as Partial<Record<SyntaxThemeTokenKey, SyntaxTokenValue>>)[key];
    resolved[key] = value !== undefined
      ? resolveValue(value)
      : MARKER_KEYS.has(key) ? 'var(--color-syntax-punctuation)'
      : key === 'diff-header' ? 'transparent'
      : syntaxTokenDefaults[`${PREFIX}${key}` as keyof typeof syntaxTokenDefaults];
  }
  return {name: input.name, tokens: resolved as SyntaxThemeTokenMap, __inputTokens: {...input.tokens}};
}

/** A token value for one color mode (Astryx `resolveSyntaxTokenForMode`). */
export function resolveSyntaxTokenForMode(value: SyntaxTokenValue, mode: 'light' | 'dark'): string {
  if (Array.isArray(value)) return mode === 'dark' ? value[1] : value[0];
  const match = value.match(/^light-dark\(([^,]+),([^)]+)\)$/);
  if (match) return (mode === 'dark' ? match[2] : match[1]).trim();
  return value;
}

/** Custom properties for a defined theme (Astryx `syntaxThemeStyle`). */
export function syntaxThemeStyle(theme: SyntaxThemeDefinition): Record<string, string> {
  const vars: Record<string, string> = {};
  for (const key of ALL_SYNTAX_KEYS) {
    const value = (theme.tokens as Partial<Record<SyntaxThemeTokenKey, string>>)[key];
    if (value !== undefined) vars[`${PREFIX}${key}`] = value;
  }
  return vars;
}

/** CSS declarations for a defined theme, no selector (Astryx `syntaxThemeToCSS`). */
export function syntaxThemeToCSS(theme: SyntaxThemeDefinition): string {
  return Object.entries(syntaxThemeStyle(theme)).map(([k, v]) => `${k}: ${v};`).join('\n  ');
}
